function [filter_coerf]  = YuleWalker( signal, decided, params )  

%  Usage      :  [filter_coerf]  = YuleWalker( signal, decided, params )  
%
%  Function   :
%     Obtain post filter coefficients using YuleWalker algorithm
%  Reference :
%      -​L. Liu, L. Li, andY. Lu, “Detection of 56GBaud PDM-QPSK 
%          generated by commercial CMOSDAC with 11GHz analog bandwidth,” 
%          in Proc. ECOC, Cannes, France, 2014, pp. 1–3. 
%
%  Author     : Rha, Hae Young.
%  Contact    : hyrha@miroandi.com   
%  Known bugs :

    if (size(signal,2) ==  0)
        filter_coerf = params.filter ;
        return
    end
    filter_size = length(params.filter );
    noise = signal - decided;
    R = zeros(1, filter_size);
%     R(1) = sum(noise .* noise);
    for idx=1:filter_size
            R(idx) = sum( noise .* circshift(noise, idx-1, 2)); 
    end 
    matrix1 = zeros(filter_size);
    for idx=1:filter_size
        for idx1=1:filter_size
            fidx = mod( abs(idx1 - idx), filter_size) +1;
            matrix1(idx, idx1) = R(fidx);
        end
    end
    R0_vector = zeros(filter_size,1);
    R0_vector(1) =R(1);
    filter_coerf = inv(matrix1) * R0_vector;
    filter_coerf = filter_coerf/(filter_coerf(1));
end 